import { useRef } from 'react';
import React, { useEffect }from 'react';
import { useNavigate } from 'react-router-dom';
import { BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, ResponsiveContainer } from 'recharts';


const sampleData = [
  { name: 'Jan', transactions: 4000 },
  { name: 'Feb', transactions: 3000 },
  { name: 'Mar', transactions: 5000 },
  { name: 'Apr', transactions: 2000 },
  { name: 'May', transactions: 6000 },
];

const samplePayments = [
  { id: 1, date: '2025-06-01', amount: '₹1,200', status: 'Success' },
  { id: 2, date: '2025-06-03', amount: '₹5,400', status: 'Failed' },
  { id: 3, date: '2025-06-05', amount: '₹3,000', status: 'Success' },
];

function Dashboard() {
  const navigate = useNavigate();

  useEffect(() => {
    const isLoggedIn = localStorage.getItem('loggedIn');
    if (!isLoggedIn) {
      navigate('/login');
    }
  }, [navigate]);

  return (
    <div style={{ padding: '100px 40px', fontFamily: 'Arial' }}>
      <h1>Welcome to your MiniPay Dashboard</h1>

      {/* Transactions Summary */}
      <section style={{ margin: '30px 0' }}>
        <h2>Transaction Summary</h2>
        <ul style={{ listStyle: 'none', padding: 0, display: 'flex', gap: '20px' }}>
          <li>Total Transactions: <strong>₹9,600</strong></li>
          <li>Successful: <strong>2</strong></li>
          <li>Failed: <strong>1</strong></li>
        </ul>
      </section>

      {/* Bar Chart */}
      <section style={{ margin: '30px 0' }}>
        <h2>Monthly Analytics</h2>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={sampleData}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="name" />
            <YAxis />
            <Tooltip />
            <Bar dataKey="transactions" fill="#8884d8" />
          </BarChart>
        </ResponsiveContainer>
      </section>

      {/* Payment History */}
      <section style={{ margin: '30px 0' }}>
        <h2>Payment History</h2>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead style={{ backgroundColor: '#f2f2f2' }}>
            <tr>
              <th style={{ padding: '10px', border: '1px solid #ddd' }}>Date</th>
              <th style={{ padding: '10px', border: '1px solid #ddd' }}>Amount</th>
              <th style={{ padding: '10px', border: '1px solid #ddd' }}>Status</th>
            </tr>
          </thead>
          <tbody>
            {samplePayments.map((payment) => (
              <tr key={payment.id}>
                <td style={{ padding: '10px', border: '1px solid #ddd' }}>{payment.date}</td>
                <td style={{ padding: '10px', border: '1px solid #ddd' }}>{payment.amount}</td>
                <td style={{ padding: '10px', border: '1px solid #ddd' }}>{payment.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      {/* Settings */}
      <section style={{ margin: '30px 0' }}>
        <h2>Settings</h2>
        <div>
          <label>
            <input type="checkbox" defaultChecked /> Enable notifications
          </label>
        </div>
        <div>
          <label>
            <input type="checkbox" /> Dark mode
          </label>
        </div>
      </section>
    </div>
  );
}

export default Dashboard;
