import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';

const resources = {
  en: { translation: { /* your translations */ } },
  // other languages...
};

i18n
  .use(initReactI18next) // binds react-i18next to i18next
  .init({
    resources,
    lng: 'en',
    fallbackLng: 'en',
    interpolation: { escapeValue: false },
  });

export default i18n;
