import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Login.css';
import vendorImage from './vendors.jpeg';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  const validateForm = () => {
    const newErrors = {};

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email) {
      newErrors.email = 'Email is required';
    } else if (!emailRegex.test(email)) {
      newErrors.email = 'Enter a valid email address';
    }

    if (!password) {
      newErrors.password = 'Password is required';
    } else if (password.length < 6) {
      newErrors.password = 'Password must be at least 6 characters';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleLogin = (e) => {
    e.preventDefault();
    if (validateForm()) {
      // Simulate login success: Set loggedIn flag in localStorage
      localStorage.setItem('loggedIn', 'true');
      console.log('Logged in:', email);
      navigate('/'); // Redirect to HomePage
    }
  };

  return (
    <div className="login-page-container" style={{ position: 'relative' }}>
      {/* Dynamic Login/Logout button at top-right */}
      <div style={{ position: 'absolute', top: 20, right: 20 }}>
        {localStorage.getItem('loggedIn') ? (
          <button
            style={{
              padding: '8px 16px',
              backgroundColor: '#007bff',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
            }}
            onClick={() => {
              localStorage.removeItem('loggedIn');
              navigate('/login');
            }}
          >
            Logout
          </button>
        ) : (
          <button
            style={{
              padding: '8px 16px',
              backgroundColor: '#007bff',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
            }}
            onClick={() => navigate('/login')}
          >
            Login
          </button>
        )}
      </div>

      {/* Existing login form UI */}
      <div className="login-container">
        <div className="login-image-section">
          <img src={vendorImage} alt="Small Vendor" className="login-image" />
        </div>
        <div className="login-form-section">
          <h2>Login to MiniPay</h2>
          <form onSubmit={handleLogin}>
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
            {errors.email && <p className="error">{errors.email}</p>}

            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            {errors.password && <p className="error">{errors.password}</p>}

            <button type="submit">Continue</button>
          </form>

          <p className="terms">
            By continuing you agree to our{' '}
            <a href="/privacy">privacy policy</a> and{' '}
            <a href="/terms">terms of use</a>.
          </p>
        </div>
      </div>
    </div>
  );
}

export default Login;
