import React, { useState } from 'react';

function AIBot({ onClose }) {
  const [messages, setMessages] = useState([{ role: 'assistant', content: 'Hi! How can I help you today?' }]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const sendMessage = async () => {
    if (!input.trim()) return;

    const newMessages = [...messages, { role: 'user', content: input }];
    setMessages(newMessages);
    setInput('');
    setLoading(true);

    try {
      const response = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer YOUR_API_KEY_HERE`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model: 'gpt-3.5-turbo', // or 'gpt-4' if available
          messages: newMessages,
        }),
      });

      const data = await response.json();
      const aiReply = data.choices[0].message.content;

      setMessages([...newMessages, { role: 'assistant', content: aiReply }]);
    } catch (err) {
      console.error(err);
      setMessages([...newMessages, { role: 'assistant', content: 'Something went wrong. Try again.' }]);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') sendMessage();
  };

  return (
    <div style={botContainerStyle}>
      <div style={botHeaderStyle}>
        <strong>MiniPay AI Assistant</strong>
        <button onClick={onClose} style={closeBtnStyle}>❌</button>
      </div>
      <div style={chatBoxStyle}>
        {messages.map((msg, idx) => (
          <div key={idx} style={{ textAlign: msg.role === 'user' ? 'right' : 'left', margin: '8px 0' }}>
            <div style={{
              display: 'inline-block',
              backgroundColor: msg.role === 'user' ? '#daf2ff' : '#f0f0f0',
              padding: '10px',
              borderRadius: '10px',
              maxWidth: '80%',
            }}>
              {msg.content}
            </div>
          </div>
        ))}
        {loading && <div style={{ fontStyle: 'italic', color: '#aaa' }}>AI is typing...</div>}
      </div>
      <div style={inputBoxStyle}>
        <input
          type="text"
          placeholder="Ask me anything..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          style={inputStyle}
        />
        <button onClick={sendMessage} style={sendBtnStyle}>Send</button>
      </div>
    </div>
  );
}

// ------------------- STYLES -------------------

const botContainerStyle = {
  position: 'fixed',
  bottom: '20px',
  right: '20px',
  width: '350px',
  height: '450px',
  backgroundColor: 'white',
  boxShadow: '0 0 15px rgba(0,0,0,0.3)',
  borderRadius: '12px',
  display: 'flex',
  flexDirection: 'column',
  overflow: 'hidden',
  zIndex: 9999,
};

const botHeaderStyle = {
  padding: '10px',
  backgroundColor: '#0b2a5b',
  color: 'white',
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
};

const closeBtnStyle = {
  background: 'transparent',
  border: 'none',
  color: 'white',
  fontSize: '1.2rem',
  cursor: 'pointer',
};

const chatBoxStyle = {
  flex: 1,
  padding: '10px',
  overflowY: 'auto',
  fontSize: '0.95rem',
};

const inputBoxStyle = {
  padding: '10px',
  borderTop: '1px solid #ddd',
  display: 'flex',
  gap: '8px',
};

const inputStyle = {
  flex: 1,
  padding: '8px',
  borderRadius: '8px',
  border: '1px solid #ccc',
  fontSize: '1rem',
};

const sendBtnStyle = {
  padding: '8px 16px',
  backgroundColor: '#4fd1c5',
  color: '#0b2a5b',
  border: 'none',
  borderRadius: '8px',
  cursor: 'pointer',
  fontWeight: 'bold',
};

export default AIBot;